The Dirty Pipe vulnerability, also known as "pipebench," is a privilege escalation flaw in the Linux kernel that allows an attacker to write to a file with elevated permissions by exploiting a race condition in the file mapping process. To exploit this vulnerability, one would typically use a specially crafted payload to overwrite a file's contents through a memory-mapped file.  

Here is a basic example of how such an exploit might be implemented in C:

```c
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>

int main() {
    int fd = open("/dev/shm/pipebench", O_RDWR | O_CREAT, 0666);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    char *map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    strcpy(map, "Hello, Dirty Pipe!");
    munmap(map, 4096);
    close(fd);

    return 0;
}
```

